      <style>

/* Base Layout */
body{
    background:#ffffff;
    font-family: "Segoe UI", Arial, sans-serif;
    color:#111;
}

.container{
    max-width:900px;
    margin:auto;
    padding:40px;
}

/* Heading */

h1{
    font-size:32px;
    font-weight:700;
    text-align:center;
    color:#000;
    margin-bottom:15px;
    letter-spacing:0.5px;
}

h1 span{
    color:#ffd700;
}

h2{
    font-size:24px;
    font-weight:700;
    margin:40px 0 20px 0;
    text-align:center;
    color:#000;
    position:relative;
}

h2:after{
    content:"";
    width:50px;
    height:2px;
    background:#ffd700;
    display:block;
    margin:10px auto 0;
}

h3{
    font-size:18px;
    font-weight:600;
    color:#ffd700;
}

/* Paragraph */

p{
    font-size:15px;
    line-height:1.8;
    color:#333;
    margin-bottom:15px;
}

/* Links */

a{
    color:#ffd700;
    font-weight:600;
    text-decoration:none;
}

a:hover{
    text-decoration:underline;
}

/* Highlight Article */

.highlight-box{
    position:relative;
    overflow:hidden;

    background:linear-gradient(180deg,#1b1b1b 0%,#111111 100%);
    color:#f5f5f5;

    border:1px solid rgba(255,215,0,.18);
    border-radius:18px;

    padding:35px;

    margin:35px 0;

    box-shadow:
        0 12px 35px rgba(0,0,0,.45),
        0 0 25px rgba(255,215,0,.08);

    transition:.35s ease;
}
.highlight-box::before{

    content:"";

    position:absolute;

    top:0;

    left:-120%;

    width:80%;

    height:100%;

    background:linear-gradient(
        120deg,
        transparent,
        rgba(255,255,255,.08),
        rgba(255,215,0,.15),
        transparent
    );

    transform:skewX(-25deg);

    animation:shineBox 7s linear infinite;
}

@keyframes shineBox{

    from{
        left:-120%;
    }

    to{
        left:180%;
    }

}
.highlight-box:hover{

    transform:translateY(-4px);

    border-color:#ffd700;

    box-shadow:
        0 18px 40px rgba(0,0,0,.5),
        0 0 30px rgba(255,215,0,.25);

}
.highlight-box h2,
.highlight-box h3{

    color:#ffd700;

    margin-bottom:18px;

    position:relative;

    padding-left:18px;

}

.highlight-box h2::before,
.highlight-box h3::before{

    content:"";

    position:absolute;

    left:0;

    top:5px;

    width:5px;

    height:22px;

    border-radius:5px;

    background:#ffd700;

}
.highlight-box p{

    color:#d6d6d6;

    line-height:1.9;

    margin-bottom:18px;

}
.highlight-box a{

    color:#ffd700;

    text-decoration:none;

    transition:.3s;

}

.highlight-box a:hover{

    color:#fff;

    text-shadow:0 0 10px #ffd700;

}
.highlight-box ul{

    margin:20px 0;

    padding:0;

    list-style:none;

}
.highlight-box li{

    position:relative;

    padding:14px 14px 14px 45px;

    margin-bottom:12px;

    background:#1d1d1d;

    border-left:4px solid #ffd700;

    border-radius:10px;

    transition:.3s;

    line-height:1.8;

}
.highlight-box li::before{

    content:"✦";

    position:absolute;

    left:16px;

    top:13px;

    color:#ffd700;

    font-size:18px;

}
.highlight-box li:hover{

    background:#262626;

    transform:translateX(8px);

    box-shadow:0 0 18px rgba(255,215,0,.15);

}

/* Info Grid */

.info-grid{
    display:grid;
    grid-template-columns:repeat(4,1fr);
    gap:16px;
    margin:30px 0;
}

.info-card{
    position:relative;

    background:#ffffff;

    border:1px solid rgba(0,0,0,.06);
    border-radius:14px;

    padding:18px 12px;

    text-align:center;

    transition:.25s ease;

    box-shadow:0 6px 18px rgba(0,0,0,.05);

    overflow:hidden;
}
.info-card::before{
    content:"";
    position:absolute;
    top:0;
    left:0;
    width:100%;
    height:3px;

    background:linear-gradient(90deg,#ffd700,transparent,#ffd700);

    opacity:.7;
}
.info-card:hover{
    transform:translateY(-4px);

    border-color:rgba(255,215,0,.35);

    box-shadow:
        0 12px 28px rgba(0,0,0,.10),
        0 0 18px rgba(255,215,0,.10);
}
.label{
    font-size:11px;
    letter-spacing:1.5px;
    text-transform:uppercase;

    color:#888;
}
.value{
    font-size:20px;
    font-weight:800;

    color:#111;

    margin-top:6px;
}
@media(max-width:900px){
    .info-grid{
        grid-template-columns:repeat(2,1fr);
    }
}

@media(max-width:500px){
    .info-grid{
        grid-template-columns:1fr;
    }
}
/* FAQ */

.faq-container{
    margin:30px 0;
    background:#ffffff;
    border:1px solid rgba(0,0,0,.06);
    border-radius:16px;

    overflow:hidden;

    box-shadow:0 10px 25px rgba(0,0,0,.06);
}

.faq-item{
    border-bottom:1px solid rgba(0,0,0,.06);
}
.faq-question{
    width:100%;
    background:none;
    border:none;

    padding:18px 16px;

    text-align:left;

    font-weight:700;
    font-size:15px;

    display:flex;
    justify-content:space-between;
    align-items:center;

    cursor:pointer;

    color:#111;

    transition:.25s ease;
}
.faq-question:hover{
    color:#b8860b;
    background:#fffaf0;
}
.faq-question::after{
    content:"\25BC";
    font-size:12px;
    color:#ffd700;
    transition:.3s ease;
}
.faq-answer{
    max-height:0;
    overflow:hidden;

    transition:max-height .35s ease, padding .3s ease;

    background:#fff;
}

.faq-answer p{
    font-size:14px;
    color:#444;
    line-height:1.7;

    padding:0 16px 15px 16px;
}

.faq-answer.open{
    max-height:300px;
    padding-top:10px;
}
.faq-item.active .faq-question{
    color:#b8860b;
}
.faq-item.active .faq-question::after{
    transform:rotate(180deg);
}
.faq-container::before{
    content:"";
    display:block;
    height:3px;
    background:linear-gradient(90deg,#ffd700,transparent,#ffd700);
}
/* Reviews */

.reviews-grid{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:18px;
    margin-top:25px;
}

.review-card{
    background:#fff;
    border:1px solid #eee;
    border-radius:10px;
    padding:18px;
    transition:0.2s;
}

.review-card:hover{
    border-color:#ffd700;
}

.review-header{
    display:flex;
    justify-content:space-between;
    margin-bottom:8px;
}

.review-name{
    font-weight:600;
}

.review-stars{
    color:#ffd700;
}

.review-text{
    font-size:14px;
    color:#444;
    line-height:1.6;
    font-style:italic;
}

.review-date{
    font-size:11px;
    color:#999;
}

/* Footer */

.footer{
    text-align:center;
    margin-top:40px;
    padding-top:20px;
    border-top:1px solid #eee;
    font-size:12px;
    color:#888;
}

/* Responsive */

@media(max-width:768px){

.info-grid{
grid-template-columns:repeat(2,1fr);
}

.reviews-grid{
grid-template-columns:1fr;
}

.container{
padding:25px;
}

h1{
font-size:24px;
}

}
/* 1. Header Review - Animasi Garis Bawah */
h2 {
    text-align: center;
    color: #b8860b;
    position: relative;
    padding-bottom: 10px;
    font-weight: 800;
}

h2::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 50px;
    height: 3px;
    background: #b8860b;
    animation: expandLine 3s infinite alternate;
}

@keyframes expandLine {
    from { width: 30px; }
    to { width: 150px; }
}

/* 2. Container Grid - Membuat Efek Scroll Halus */
.reviews-grid {
    display: flex;
    gap: 20px;
    padding: 20px 10px;
    overflow-x: auto; /* Memungkinkan scroll di HP */
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch;
}

/* 3. Review Card - Animasi Floating & Glow */
.review-card {
    min-width: 280px; /* Agar kartu tidak gepeng saat scroll */
    background: #ffffff;
    border: 1px solid #f0f0f0;
    border-radius: 15px;
    padding: 20px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.03);
    transition: all 0.3s ease;
    animation: fadeInUp 0.8s ease backwards;
}

/* Delay animasi untuk setiap kartu agar muncul bergantian */
.review-card:nth-child(1) { animation-delay: 0.1s; }
.review-card:nth-child(2) { animation-delay: 0.2s; }
.review-card:nth-child(3) { animation-delay: 0.3s; }
.review-card:nth-child(4) { animation-delay: 0.4s; }
.review-card:nth-child(5) { animation-delay: 0.5s; }
.review-card:nth-child(6) { animation-delay: 0.6s; }

.review-card:hover {
    transform: translateY(-10px);
    border-color: #ffd700;
    box-shadow: 0 15px 30px rgba(184, 134, 11, 0.1);
}

/* 4. Animasi Bintang - Berdenyut Lembut */
.review-stars {
    color: #ffd700;
    display: inline-block;
    animation: starPulse 2s infinite;
}

@keyframes starPulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.1); opacity: 0.7; }
}

/* 5. Review Text - Slide Up saat Hover */
.review-text {
    font-style: italic;
    color: #555;
    line-height: 1.6;
    transition: color 0.3s;
}

.review-card:hover .review-text {
    color: #000;
}

/* Keyframes Utama */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
